using System.Text;

namespace TCPipeAutoDraw.UI.Studio
{
    internal static class CDBoxStudioQuantityAttributeEditorPage
    {
        public static string BuildEmbeddedSection() { return "<section id=\"quantityAttributeEditorPage\" style=\"display:none\"></section>"; }

        public static string BuildStandaloneDocument(CDBoxStudioSettings settings, string logFilePath, string documentId, string handle)
        {
            settings = settings ?? new CDBoxStudioSettings(); settings.Normalize();
            var html = new StringBuilder();
            html.Append("<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>CDBox Studio - 属性编辑器</title><style>").Append(BuildStyles(true)).Append("</style></head>");
            html.Append("<body data-theme=\"").Append(Html(settings.Theme)).Append("\" class=\"").Append(settings.AnimationsEnabled ? "" : "no-animations").Append("\"><section id=\"quantityAttributeEditorPage\" style=\"height:100%\"></section><div id=\"qaToast\" class=\"qa-toast-host\"></div><script>");
            html.Append(BuildComponentScript());
            html.Append("function qaPost(n,a){try{chrome.webview.postMessage('studio|'+n+'|'+encodeURIComponent(a||''));}catch(ex){}}function qaToast(m,k){var h=document.getElementById('qaToast'),e=document.createElement('div');e.className='qa-toast '+(k||'info');e.textContent=m||'';h.appendChild(e);setTimeout(function(){e.classList.add('show');},10);setTimeout(function(){e.classList.remove('show');setTimeout(function(){e.remove();},180);},3000);}window.CDBoxStudioToast=qaToast;window.CDBoxQuantityAttributeEditorPage.create({rootId:'quantityAttributeEditorPage',post:qaPost,toast:qaToast,standalone:true,documentId:").Append(Js(documentId)).Append(",handle:").Append(Js(handle)).Append("});setTimeout(function(){qaPost('ready','quantity-attribute-editor');},50);");
            html.Append("</script><span style=\"display:none\">").Append(Html(logFilePath)).Append("</span></body></html>");
            return html.ToString();
        }

        public static string BuildStyles(bool standalone)
        {
            string root = standalone ? @":root{--bg:#f5f7fb;--panel:#fff;--panel2:#f8fafc;--text:#172033;--muted:#64748b;--line:#dce5f1;--brand:#326fea;--brand2:#7c3aed;--danger:#b91c1c}body[data-theme='fresh']{--bg:#f2f6ff;--panel:#fff;--panel2:#edf4ff;--line:#d7e5ff}body[data-theme='dark']{--bg:#0f172a;--panel:#172033;--panel2:#111827;--text:#e5e7eb;--muted:#94a3b8;--line:#2b3a50;--brand:#60a5fa;--brand2:#a78bfa}html,body{height:100%;margin:0;overflow:hidden;background:var(--bg);font-family:'Microsoft YaHei UI','Segoe UI',sans-serif;color:var(--text)}" : string.Empty;
            return root + @"
#quantityAttributeEditorPage{height:100%;min-height:0}.qa-page,.qa-page *{box-sizing:border-box}.qa-page{height:100%;overflow:auto;padding:18px 20px 30px;background:linear-gradient(180deg,rgba(222,233,255,.52),transparent 230px),var(--bg);color:var(--text)}.qa-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:14px}.qa-head h2{margin:0;font-size:25px}.qa-head p{margin:5px 0 0;color:var(--muted);font-size:13px}.qa-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.qa-btn{height:37px;padding:0 13px;border:1px solid var(--line);border-radius:11px;background:var(--panel);color:var(--text);font:inherit;font-weight:750;cursor:pointer}.qa-btn:hover{transform:translateY(-1px)}.qa-btn.primary{border:0;color:#fff;background:linear-gradient(135deg,var(--brand),var(--brand2))}.qa-btn.warning{color:#b45309;border-color:#fdba74;background:#fff7ed}.qa-btn.danger{color:var(--danger);border-color:#fecaca}.qa-btn:disabled{opacity:.45;cursor:not-allowed;transform:none}.qa-empty{min-height:510px;display:grid;place-items:center;text-align:center;background:var(--panel);border:1px solid var(--line);border-radius:20px;box-shadow:0 15px 34px rgba(30,50,90,.07)}.qa-empty svg{width:62px;height:62px;fill:none;stroke:var(--brand);stroke-width:1.5}.qa-empty h3{margin:15px 0 7px}.qa-empty p{color:var(--muted);max-width:520px;line-height:1.7}.qa-object{display:grid;grid-template-columns:minmax(0,1.2fr) repeat(3,minmax(130px,.55fr));gap:10px;margin-bottom:13px}.qa-object>div{padding:13px 15px;background:var(--panel);border:1px solid var(--line);border-radius:14px}.qa-object span{display:block;color:var(--muted);font-size:11px}.qa-object strong{display:block;margin-top:5px;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.qa-status{padding:10px 13px;margin-bottom:13px;border-radius:12px;background:#eef7ff;color:#245c9f;border:1px solid #cfe4fb;font-size:12px}.qa-layout{display:grid;grid-template-columns:210px minmax(0,1fr);gap:14px;align-items:start}.qa-nav{position:sticky;top:0;padding:9px;background:var(--panel);border:1px solid var(--line);border-radius:16px}.qa-nav button{display:block;width:100%;padding:11px;border:0;border-radius:10px;background:transparent;color:var(--muted);text-align:left;font:inherit;font-weight:750;cursor:pointer}.qa-nav button.active{background:var(--panel2);color:var(--brand)}.qa-card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:17px;box-shadow:0 10px 25px rgba(30,50,90,.055);margin-bottom:13px}.qa-card h3{margin:0 0 4px;font-size:16px}.qa-card>p{margin:0 0 15px;color:var(--muted);font-size:12px}.qa-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.qa-field{min-width:0}.qa-field.wide{grid-column:1/-1}.qa-field>span{display:block;margin-bottom:6px;color:var(--muted);font-size:11px;font-weight:750}.qa-field input[type=text],.qa-field input[type=number],.qa-field select,.qa-field textarea{width:100%;min-height:39px;border:1px solid var(--line);border-radius:10px;background:var(--panel2);color:var(--text);padding:8px 10px;font:inherit;outline:0}.qa-field textarea{min-height:145px;resize:vertical;line-height:1.6}.qa-field input:focus,.qa-field select:focus,.qa-field textarea:focus{border-color:var(--brand);box-shadow:0 0 0 3px rgba(50,111,234,.11)}.qa-switch{display:flex;align-items:center;gap:9px;height:39px}.qa-switch input{accent-color:var(--brand);width:17px;height:17px}.qa-readonly{min-height:39px;padding:10px;border:1px dashed var(--line);border-radius:10px;background:var(--panel2);color:var(--muted)}.qa-node-actions{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:13px}.qa-dirty{display:none;color:#b45309;margin-left:8px}.qa-dirty.show{display:inline}.qa-toast-host{position:fixed;right:22px;bottom:22px;display:grid;gap:8px;z-index:1200}.qa-toast{opacity:0;transform:translateY(8px);padding:11px 14px;border-radius:12px;background:#172033;color:#fff;transition:.18s}.qa-toast.show{opacity:1;transform:none}.qa-toast.success{background:#047857}.qa-toast.error{background:#b91c1c}.no-animations *{animation:none!important;transition:none!important}@media(max-width:980px){.qa-head{flex-direction:column}.qa-actions{justify-content:flex-start}.qa-object{grid-template-columns:1fr 1fr}.qa-layout{grid-template-columns:1fr}.qa-nav{position:static;display:flex;overflow:auto}.qa-nav button{width:auto;white-space:nowrap}}@media(max-width:680px){.qa-grid,.qa-object{grid-template-columns:1fr}}
";
        }

        public static string BuildComponentScript()
        {
            return @"
(function(w){var instances=[];function esc(v){return String(v==null?'':v).replace(/[&<>""']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','""':'&quot;',""'"":'&#39;'}[c]||c;});}function clone(v){return JSON.parse(JSON.stringify(v||{}));}
var common=[['Enabled','参与工程量统计','bool'],['Material','管材','text'],['Diameter','规格 / 管径','text'],['UseManualLength','使用手动统计长度','bool'],['ManualLength','手动统计长度 m','number'],['DrawLengthWidthHeightAnnotation','标注长宽高','bool']];
var main=[['StartNode','起点井','text'],['StartDepth','起点深度 m','number'],['EndNode','终点井','text'],['EndDepth','终点深度 m','number'],['AverageDepth','平均深度 m','number'],['TrenchWidth','开挖宽度 m','number'],['RoadThickness','原路面结构层 m','number'],['ExcavationType','开挖方式','select','机械开挖|人工开挖'],['BackfillType','回填类型','select','中粗砂回填|原土回填|混合/特殊']];
var branch=[['BranchType','支管类型','select','砼恢复|原土回填|明管|并埋|雨水'],['BranchIncludeInCalculation','支管加入计算','bool'],['BranchDepth','支管开挖深度 m','number'],['TrenchWidth','开挖宽度 m','number'],['RoadThickness','原路面结构层 m','number'],['ExcavationType','开挖方式','select','人工开挖|机械开挖'],['BackfillType','回填类型','select','中粗砂回填|原土回填|混合/特殊']];
var node=[['Enabled','参与工程量统计','bool'],['NodeNo','节点 / 井编号','text'],['WellSpec','井规格 / 直径','text'],['WellMaterialType','井材料类型','select','成品塑料井|砖砌井|现浇混凝土井'],['WellCoverMaterial','井盖类型 / 材料','select','混凝土井盖|铸铁井盖'],['WellType','井类型','select','检查井|沉泥井|跌水井'],['SiltWellDeductDepth500','500 沉泥扣减 m','number'],['SiltWellDeductDepth700','700 沉泥扣减 m','number'],['GroundElevation','自然标高 m','number'],['WellDepth','井深 m','number'],['ShaftLength','井筒长度 m','number'],['RoadThickness','原路面结构层 m','number'],['ExcavationLength','开挖长 m','number'],['ExcavationWidth','开挖宽 m','number'],['ExcavationType','开挖方式','select','机械开挖|人工开挖'],['BackfillType','回填类型','select','中粗砂回填|原土回填|混合/特殊'],['CoverPlate','承压盖板','text']];
var structure=[['BackfillStructure','结构层（每行一层）','textarea'],['SandCushionThickness','中粗砂垫层厚度 m','number'],['GravelCushionThickness','碎石垫层厚度 m','number'],['C25RestoreThickness','C25 恢复厚度 m','number'],['PipeOuterDiameter','管道外径 / 计算直径 m','number'],['DeductPipeVolume','扣除管身体积','bool'],['Remark','备注','textarea']];
function Editor(o){this.o=o||{};this.root=document.getElementById(this.o.rootId||'quantityAttributeEditorPage');this.ctx=null;this.attrs={};this.dirty=false;this.section='basic';}
Editor.prototype.post=function(n,a){if(this.o.post)this.o.post(n,a||'');};Editor.prototype.toast=function(m,k){if(this.o.toast)this.o.toast(m,k);};Editor.prototype.request=function(extra){var p={documentId:this.ctx?this.ctx.documentId:(this.o.documentId||''),handle:this.ctx?this.ctx.handle:(this.o.handle||''),attributes:this.collect()};if(extra)Object.keys(extra).forEach(function(k){p[k]=extra[k];});return JSON.stringify(p);};
Editor.prototype.init=function(){this.renderEmpty('请选择需要编辑的工程量对象。');this.post('getQuantityAttributeContext',JSON.stringify({documentId:this.o.documentId||'',handle:this.o.handle||''}));return this;};Editor.prototype.open=function(){return this;};Editor.prototype.suspend=function(){return this;};
Editor.prototype.renderEmpty=function(msg){this.root.innerHTML='<div class=""qa-page""><header class=""qa-head""><div><h2>属性编辑器 <small style=""font-size:12px;color:var(--brand)"">Preview 9</small></h2><p>主管、支管、节点 / 检查井共用同一属性编辑工作区。</p></div><div class=""qa-actions""><button class=""qa-btn primary"" data-act=""select"">选择对象</button>'+(this.o.standalone?'<button class=""qa-btn danger"" data-act=""close"">关闭</button>':'')+'</div></header><div class=""qa-empty""><div><svg viewBox=""0 0 64 64""><path d=""M12 15h40v34H12zM20 24h24M20 32h18M20 40h12""/></svg><h3>尚未选择对象</h3><p>'+esc(msg)+'</p><button class=""qa-btn primary"" data-act=""select"">从 CAD 中选择</button></div></div></div>';this.bind();};
Editor.prototype.load=function(c){this.ctx=c||{};if(!c||!c.selected){this.renderEmpty(c&&c.message||'请选择对象。');return;}this.attrs=clone(c.attributes);this.dirty=false;this.render();};
Editor.prototype.render=function(){var c=this.ctx,a=this.attrs,kind=c.inferredKind||a.ObjectKind||'主管',isNode=kind.indexOf('井')>=0,isBranch=kind.indexOf('支')>=0;var fields=isNode?node:(isBranch?common.concat(branch):common.concat(main)),structureFields=isNode?structure.filter(function(x){return x[0]!=='PipeOuterDiameter'&&x[0]!=='DeductPipeVolume';}):structure;var buttons='<button class=""qa-btn primary"" data-act=""select"">重新选择</button><button class=""qa-btn"" data-act=""refresh"">智能刷新</button><button class=""qa-btn warning"" data-act=""default"">按默认表重填</button><button class=""qa-btn"" data-act=""legacy"">打开旧版</button>'+(this.o.standalone?'':'<button class=""qa-btn"" data-act=""standalone"">独立窗口</button>')+'<button class=""qa-btn primary"" data-act=""save"">保存<span class=""qa-dirty"">●</span></button>'+(this.o.standalone?'<button class=""qa-btn danger"" data-act=""close"">关闭</button>':'');
this.root.innerHTML='<div class=""qa-page""><header class=""qa-head""><div><h2>属性编辑器 <small style=""font-size:12px;color:var(--brand)"">Preview 9</small></h2><p>编辑 '+esc(kind)+' 属性；旧 Xrecord 字段保持兼容。</p></div><div class=""qa-actions"">'+buttons+'</div></header><div class=""qa-object""><div><span>对象 / 图层</span><strong>'+esc(c.objectTypeName)+' · '+esc(c.layerName)+'</strong></div><div><span>类型</span><strong>'+esc(kind)+'</strong></div><div><span>Handle</span><strong>'+esc(c.handle)+'</strong></div><div><span>CAD / 有效长度</span><strong>'+Number(c.cadLength||0).toFixed(2)+' / '+Number(c.effectiveLength||0).toFixed(2)+' m</strong></div></div><div class=""qa-status"">'+esc(c.message||'')+'</div>'+(isNode||isBranch?'':this.nodeButtons())+'<div class=""qa-layout""><nav class=""qa-nav""><button data-sec=""basic"" class=""active"">基本与工程参数</button><button data-sec=""structure"">结构层与扣减</button><button data-sec=""meta"">图层识别信息</button></nav><main><section data-panel=""basic"" class=""qa-card""><h3>基本与工程参数</h3><p>字段按对象类型自动切换。</p><div class=""qa-grid"">'+this.fields(fields)+'</div></section><section data-panel=""structure"" class=""qa-card"" style=""display:none""><h3>结构层、扣减与备注</h3><p>结构层保持与默认表和旧版编辑器相同的文本格式。</p><div class=""qa-grid"">'+this.fields(structureFields)+'</div></section><section data-panel=""meta"" class=""qa-card"" style=""display:none""><h3>图层识别信息</h3><p>以下信息由图层管理器维护，只读展示。</p><div class=""qa-grid"">'+this.readonly('图层父属性',a.LayerParentGroup)+this.readonly('图层分类',a.LayerParentClass)+this.readonly('图层标签',a.LayerTags)+'</div></section></main></div></div>';this.bind();};
Editor.prototype.nodeButtons=function(){return '<div class=""qa-node-actions""><button class=""qa-btn"" data-act=""start"">选择起点井</button><button class=""qa-btn"" data-act=""end"">选择终点井</button><button class=""qa-btn"" data-act=""swap"">调换起终点</button></div>';};
Editor.prototype.readonly=function(l,v){return '<label class=""qa-field""><span>'+esc(l)+'</span><div class=""qa-readonly"">'+esc(v||'--')+'</div></label>';};Editor.prototype.fields=function(list){var self=this;return list.map(function(f){var k=f[0],l=f[1],t=f[2],v=self.attrs[k];if(t==='bool')return '<label class=""qa-field""><span>'+esc(l)+'</span><div class=""qa-switch""><input type=""checkbox"" data-key=""'+k+'"" '+(v?'checked':'')+'><b>'+(v?'已启用':'未启用')+'</b></div></label>';if(t==='select')return '<label class=""qa-field""><span>'+esc(l)+'</span><select data-key=""'+k+'"">'+String(f[3]||'').split('|').map(function(x){return '<option '+(String(v||'')===x?'selected':'')+'>'+esc(x)+'</option>';}).join('')+'</select></label>';if(t==='textarea')return '<label class=""qa-field wide""><span>'+esc(l)+'</span><textarea data-key=""'+k+'"">'+esc(v||'')+'</textarea></label>';return '<label class=""qa-field""><span>'+esc(l)+'</span><input data-key=""'+k+'"" type=""'+(t==='number'?'number':'text')+'"" step=""any"" value=""'+esc(v==null?'':v)+'""></label>';}).join('');};
Editor.prototype.collect=function(){if(!this.root)return this.attrs;var a=clone(this.attrs);[].slice.call(this.root.querySelectorAll('[data-key]')).forEach(function(e){var k=e.getAttribute('data-key');a[k]=e.type==='checkbox'?e.checked:(e.type==='number'?(e.value===''?0:Number(e.value)):e.value);});this.attrs=a;return a;};
Editor.prototype.bind=function(){var self=this;this.root.onclick=function(e){var b=e.target.closest('[data-act]');if(b)self.act(b.getAttribute('data-act'));var n=e.target.closest('[data-sec]');if(n)self.show(n.getAttribute('data-sec'));};this.root.oninput=function(e){if(e.target.matches('[data-key]')){self.dirty=true;var d=self.root.querySelector('.qa-dirty');if(d)d.classList.add('show');if(e.target.type==='checkbox'){var b=e.target.parentNode.querySelector('b');if(b)b.textContent=e.target.checked?'已启用':'未启用';}}};};
Editor.prototype.show=function(s){this.root.querySelectorAll('[data-panel]').forEach(function(x){x.style.display=x.getAttribute('data-panel')===s?'block':'none';});this.root.querySelectorAll('[data-sec]').forEach(function(x){x.classList.toggle('active',x.getAttribute('data-sec')===s);});};Editor.prototype.act=function(a){if(a==='select'){this.post('selectQuantityAttributeObject',this.request());return;}if(a==='close'){this.post('close','');return;}if(!this.ctx||!this.ctx.selected)return;if(a==='save')this.post('saveQuantityAttributes',this.request());else if(a==='refresh')this.post('refreshQuantityAttributes',this.request());else if(a==='default')this.post('reloadQuantityAttributeDefault',this.request());else if(a==='start'||a==='end')this.post('selectQuantityAttributeNode',this.request({forStart:a==='start'}));else if(a==='legacy')this.post('openLegacyQuantityAttributeEditor',this.request());else if(a==='standalone')this.post('openQuantityAttributeEditorWindow',this.request());else if(a==='swap'){var x=this.collect(),n=x.StartNode,d=x.StartDepth;x.StartNode=x.EndNode;x.StartDepth=x.EndDepth;x.EndNode=n;x.EndDepth=d;this.attrs=x;this.dirty=true;this.render();}};
function dispatch(c){instances.forEach(function(x){x.load(c);});}w.CDBoxQuantityAttributeEditorPage={create:function(o){var x=new Editor(o);instances.push(x);return x.init();}};w.CDBoxQuantityAttributeEditorLoad=dispatch;w.CDBoxQuantityAttributeEditorFailed=function(m){instances.forEach(function(x){x.toast(m,'error');});};})(window);
";
        }

        private static string Html(string value) { return (value ?? string.Empty).Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;").Replace("'", "&#39;"); }
        private static string Js(string value) { return "'" + (value ?? string.Empty).Replace("\\", "\\\\").Replace("'", "\\'").Replace("\r", "\\r").Replace("\n", "\\n") + "'"; }
    }
}
